'use strict';

function normalizeNames(names) {
  if (!Array.isArray(names) || names.length !== 2) throw new TypeError('names must contain two strings');
  const result = names.map((name) => {
    if (typeof name !== 'string' || name.trim() === '') throw new TypeError('invalid player name');
    return name.trim();
  });
  if (result[0] === result[1]) throw new TypeError('player names must be distinct');
  return result;
}

function createSession(names) {
  return { players: normalizeNames(names), piles: [3, 4, 5], turn: 0, status: 'active', winner: null };
}

function validateSession(session) {
  if (!session || typeof session !== 'object' || !Array.isArray(session.players) ||
      session.players.length !== 2 || !Array.isArray(session.piles) || session.piles.length !== 3 ||
      !session.piles.every((value) => Number.isInteger(value) && value >= 0) ||
      (session.turn !== 0 && session.turn !== 1) ||
      (session.status !== 'active' && session.status !== 'won')) {
    throw new TypeError('malformed session');
  }
  normalizeNames(session.players);
}

function takeTokens(session, pileIndex, count) {
  validateSession(session);
  if (session.status !== 'active') throw new RangeError('session is complete');
  if (!Number.isInteger(pileIndex) || pileIndex < 0 || pileIndex > 2 ||
      !Number.isInteger(count) || count < 1 || count > 2 || count > session.piles[pileIndex]) {
    throw new RangeError('invalid move');
  }
  const piles = session.piles;
  piles[pileIndex] -= count;
  const won = piles.every((value) => value === 0);
  return {
    players: session.players.slice(),
    piles,
    turn: won ? session.turn : 1 - session.turn,
    status: won ? 'won' : 'active',
    winner: won ? session.players[session.turn] : null
  };
}

function resetSession(names) {
  return createSession(names);
}

module.exports = { createSession, takeTokens, resetSession };

