'use strict';

const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api).sort(), ['createSession', 'resetSession', 'takeTokens']);
const { createSession, takeTokens, resetSession } = api;

const names = ['  Alice  ', 'Bob'];
const session = createSession(names);
assert.deepStrictEqual(session, {
  players: ['Alice', 'Bob'],
  piles: [3, 4, 5],
  turn: 0,
  status: 'active',
  winner: null
});
assert.deepStrictEqual(names, ['  Alice  ', 'Bob']);
assert.notStrictEqual(session.players, names);

names[0] = 'Changed';
assert.deepStrictEqual(session.players, ['Alice', 'Bob']);

const moved = takeTokens(session, 1, 2);
assert.deepStrictEqual(moved, {
  players: ['Alice', 'Bob'],
  piles: [3, 2, 5],
  turn: 1,
  status: 'active',
  winner: null
});
assert.deepStrictEqual(session.piles, [3, 4, 5]);
assert.strictEqual(session.turn, 0);
assert.notStrictEqual(moved, session);
assert.notStrictEqual(moved.players, session.players);
assert.notStrictEqual(moved.piles, session.piles);

moved.players[0] = 'Mutated';
moved.piles[0] = 0;
assert.deepStrictEqual(session.players, ['Alice', 'Bob']);
assert.deepStrictEqual(session.piles, [3, 4, 5]);

let game = createSession([' Alice ', ' Bob ']);
game = takeTokens(game, 0, 2);
game = takeTokens(game, 0, 1);
game = takeTokens(game, 1, 2);
game = takeTokens(game, 1, 2);
game = takeTokens(game, 2, 2);
game = takeTokens(game, 2, 2);
const beforeWin = game;
game = takeTokens(game, 2, 1);
assert.deepStrictEqual(game.piles, [0, 0, 0]);
assert.strictEqual(game.status, 'won');
assert.strictEqual(game.winner, 'Alice');
assert.strictEqual(game.turn, 0);
assert.strictEqual(beforeWin.status, 'active');
assert.deepStrictEqual(beforeWin.piles, [0, 0, 1]);
assert.throws(() => takeTokens(game, 0, 1), RangeError);

const resetNames = [' X ', ' Y '];
const reset = resetSession(resetNames);
assert.deepStrictEqual(reset, createSession(resetNames));
assert.notStrictEqual(reset.players, resetNames);
assert.notStrictEqual(reset.piles, session.piles);

for (const badNames of [null, {}, ['A'], ['A', 'B', 'C'], ['', 'B'], ['   ', 'B'], ['A', ' A '], ['A', 2]]) {
  assert.throws(() => createSession(badNames), TypeError);
  assert.throws(() => resetSession(badNames), TypeError);
}

for (const [pile, count] of [[-1, 1], [3, 1], [1.5, 1], [0, 0], [0, 3], [0, 1.5]]) {
  assert.throws(() => takeTokens(session, pile, count), RangeError);
}
assert.throws(() => takeTokens(takeTokens(takeTokens(session, 0, 1), 0, 1), 0, 2), RangeError);

for (const badSession of [null, {}, [], { ...session, players: ['Alice'] }, { ...session, piles: [3, 4] }, { ...session, turn: 2 }, { ...session, status: 'broken' }]) {
  assert.throws(() => takeTokens(badSession, 0, 1), TypeError);
}

